class Solution:
    def beautifulSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        cnt_0 = [0] * (n + 1)  # vowels count prefix
        cnt_1 = [0] * (n + 1)  # consonants count prefix
        res = 0

        # Initialize counts for each position
        for i in range(n):
            if s[i] in 'aeiou':
                cnt_0[i + 1] = cnt_0[i] + 1
            else:
                cnt_1[i + 1] = cnt_1[i] + 1

        # Check all substrings
        for i in range(n):
            for j in range(i + 1, n + 1):
                # Calculate vowel and consonant count in substring s[i:j]
                vowels = cnt_0[j] - cnt_0[i]
                consonants = cnt_1[j] - cnt_1[i]

                # Check if substring is beautiful
                if vowels == consonants and (vowels * consonants) % k == 0:
                    res += 1

        return res
